const body = $json.body || $json;
const company = body.company_name || body.company || '';
const contact = body.contact_name || body.name || '';
const email = body.contact_email || body.email || '';
const platform = body.platform || 'email';
const profileUrl = body.profile_url || '';
const industry = body.industry || '';
const notes = body.notes || '';

if (!company && !contact) {
  return [{ json: { _error: true, message: 'company_name or contact_name required' } }];
}

const fields = {
  company_name: company || '(Unknown)',
  contact_name: contact || '(Unknown)',
  stage: 'New',
  notes: `Source: outreach\nPlatform: ${platform}\nProfile: ${profileUrl}\nIndustry: ${industry}\n${notes}`
};
if (email) fields.email = email;

return [{ json: { fields, company, contact, platform, profileUrl, industry, notes: fields.notes, _error: false } }];

// Collect inputs from both parallel branches
const prospectData = $('out-validate-prospect').first().json;
const recordId = $('out-create-prospect').first().json.id || 'unknown';

// Parse system learnings (may have failed gracefully)
let learningsText = '';
try {
  const learningsResp = $('out-fetch-learnings').first().json;
  const records = learningsResp.records || [];
  if (records.length > 0) {
    learningsText = '\n\n## SYSTEM LEARNINGS (what has worked in past outreach)\n';
    for (const rec of records) {
      const f = rec.fields || {};
      learningsText += `- [${f.category || 'general'}] ${f.learning || f.insight || f.description || JSON.stringify(f)}\n`;
    }
  }
} catch (e) {
  learningsText = '';
}

const systemPrompt = `You are Cosmisk's outreach copywriter. Cosmisk is a UGC agency in India offering UGC ads, AI-generated ads, mashup ads, media buying, and ad account audits.

You write cold outreach messages that get replies. You NEVER write generic, spammy messages.

ABSOLUTE BANS — never use these phrases:
- "I hope this email finds you well"
- "I came across your company"
- "I'd love to connect"
- "Let's schedule a quick call"
- "synergy"
- "game-changer"
- "best-in-class"

RULES:
1. Open with something SPECIFIC about THEIR business (a recent ad they ran, their industry challenge, their growth stage, a specific product they sell)
2. Each message MUST be under 150 words
3. CTA must be a SPECIFIC question, not a generic "let's chat"
4. Subject line must create curiosity without clickbait
5. Match platform tone: Instagram DM = casual, Email = slightly formal, LinkedIn = professional
${learningsText}`;

const userPrompt = `Generate 3 DISTINCT outreach messages for this prospect. Each takes a completely different angle:

**Prospect Details:**
- Company: ${prospectData.company}
- Contact: ${prospectData.contact}
- Platform: ${prospectData.platform}
- Profile/Website: ${prospectData.profileUrl || 'not provided'}
- Industry: ${prospectData.industry || 'not specified'}

**Message A — Pain-Point Focused:**
Identify their most likely pain point based on their industry and size. Show how UGC/AI ads specifically solve THAT problem. Be empathetic, not pushy.

**Message B — Results-Focused:**
Lead with a specific number or case study result (e.g., "We helped a ${prospectData.industry || 'similar'} brand cut CAC by 40% with UGC"). Back it with social proof.

**Message C — Curiosity-Focused:**
Intriguing hook that makes them want to reply. Minimal pitch. Create an open loop. Ask a question that's hard to ignore.

For EACH message, also provide:
- subject_line (for email) or hook_line (for DM)
- brief research note about the brand (1-2 sentences of what you found/inferred)

Return as JSON:
{
  "messages": [
    {
      "angle": "pain_point",
      "subject_line": "...",
      "body": "...",
      "research_note": "..."
    },
    {
      "angle": "results",
      "subject_line": "...",
      "body": "...",
      "research_note": "..."
    },
    {
      "angle": "curiosity",
      "subject_line": "...",
      "body": "...",
      "research_note": "..."
    }
  ]
}`;

return [{ json: { systemPrompt, userPrompt, recordId, prospect: prospectData } }];

const geminiResult = $json;
const prev = $('out-build-3msg-prompt').first().json;

let messages = [];
try {
  const text = (geminiResult.candidates || [])[0]?.content?.parts?.[0]?.text || '';
  let cleaned = text.replace(/^```json\s*/i, '').replace(/^```\s*/m, '').replace(/\s*```\s*$/m, '').trim();
  const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    messages = parsed.messages || [];
  }
  // Truncation fallback: extract individual message objects
  if (messages.length === 0) {
    const objRegex = /\{[^{}]*"angle"\s*:\s*"[^"]+"[^{}]*"body"\s*:\s*"[^"]*"[^{}]*\}/g;
    const matches = cleaned.match(objRegex) || [];
    for (const m of matches) {
      try { messages.push(JSON.parse(m)); } catch (e) { /* skip */ }
    }
  }
} catch (e) {
  // Will fall through to fallback below
}

if (messages.length === 0) {
  // Fallback: generate basic messages
  const p = prev.prospect;
  messages = [
    {
      angle: 'pain_point',
      subject_line: `${p.company || 'Your brand'} + UGC`,
      body: `Hi ${p.contact || 'there'}, most ${p.industry || 'D2C'} brands struggle with ad fatigue — the same creatives stop converting after 2-3 weeks. UGC solves this by giving you a constant stream of fresh, authentic content. We build UGC pipelines for brands like yours. What's your current biggest bottleneck with ad creatives?`,
      research_note: 'Fallback — Gemini parse failed'
    },
    {
      angle: 'results',
      subject_line: `40% lower CAC for ${p.industry || 'brands'} like ${p.company || 'yours'}`,
      body: `Hi ${p.contact || 'there'}, we recently helped a ${p.industry || 'similar'} brand cut their customer acquisition cost by 40% using UGC-first ad creatives. The key was matching creator style to their audience demographics. Would you be open to seeing the breakdown of how we did it?`,
      research_note: 'Fallback — Gemini parse failed'
    },
    {
      angle: 'curiosity',
      subject_line: `Quick question about ${p.company || 'your'} ads`,
      body: `Hi ${p.contact || 'there'}, I noticed something interesting about the ${p.industry || 'D2C'} ad landscape that directly relates to ${p.company || 'your brand'}. Are you currently running any creator-style content in your paid campaigns, or mostly polished brand creatives?`,
      research_note: 'Fallback — Gemini parse failed'
    }
  ];
}

return [{ json: { messages, recordId: prev.recordId, prospect: prev.prospect } }];

const data = $json;
const messages = data.messages;
const prospect = data.prospect;

const systemPrompt = `You are an expert outreach evaluator for Cosmisk, a UGC agency. You evaluate cold outreach messages with brutal honesty. Score STRICTLY — most messages should score 5-7, not 8-10.

Score each message on these 5 criteria (1-10 each, 50 max):

1. **personalization** — Does it reference something SPECIFIC about THEIR business? Generic industry mentions = 3-4. Specific product/campaign/metric = 7-8. Deep insight = 9-10.
2. **value_clarity** — Is it immediately clear what they'd GET? Vague "help your brand" = 3-4. Specific outcome with numbers = 7-8.
3. **brevity** — Is it under 150 words and scannable in 30 seconds? Over 150 = max 4. Under 100 with impact = 8-10.
4. **cta_strength** — Is the CTA a specific question? Generic "let's chat" = 2-3. Specific question they want to answer = 7-8.
5. **spam_avoidance** — Does it avoid spam triggers and sound human? Contains banned phrases or sounds like mass email = 1-3. Feels like a real person wrote it = 7-8.`;

const userPrompt = `Evaluate these 3 outreach messages for:
Company: ${prospect.company}
Contact: ${prospect.contact}
Platform: ${prospect.platform}
Industry: ${prospect.industry || 'unknown'}

---
Message A (${messages[0]?.angle || 'pain_point'}):
Subject: ${messages[0]?.subject_line || 'N/A'}
${messages[0]?.body || 'N/A'}

---
Message B (${messages[1]?.angle || 'results'}):
Subject: ${messages[1]?.subject_line || 'N/A'}
${messages[1]?.body || 'N/A'}

---
Message C (${messages[2]?.angle || 'curiosity'}):
Subject: ${messages[2]?.subject_line || 'N/A'}
${messages[2]?.body || 'N/A'}

---

For each message, return scores and a 1-sentence critique. Then pick the best one.

Return JSON:
{
  "evaluations": [
    {
      "angle": "pain_point",
      "personalization": 7,
      "value_clarity": 6,
      "brevity": 8,
      "cta_strength": 5,
      "spam_avoidance": 7,
      "total": 33,
      "critique": "..."
    },
    { ... },
    { ... }
  ],
  "best_index": 0,
  "best_angle": "pain_point",
  "improvement_notes": "One sentence on what would make the best message even better"
}`;

return [{ json: { systemPrompt, userPrompt, messages, recordId: data.recordId, prospect } }];

const geminiResult = $json;
const prev = $('out-build-eval-prompt').first().json;
const messages = prev.messages;

let evaluation = null;
let bestIndex = 0;
let bestTotal = 0;
let improvementNotes = '';
let needsRetry = false;

try {
  const text = (geminiResult.candidates || [])[0]?.content?.parts?.[0]?.text || '';
  let cleaned = text.replace(/^```json\s*/i, '').replace(/^```\s*/m, '').replace(/\s*```\s*$/m, '').trim();
  const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    evaluation = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  // evaluation stays null
}

if (evaluation && evaluation.evaluations) {
  // Find best message by total score
  for (let i = 0; i < evaluation.evaluations.length; i++) {
    const ev = evaluation.evaluations[i];
    const total = ev.total || (ev.personalization + ev.value_clarity + ev.brevity + ev.cta_strength + ev.spam_avoidance) || 0;
    if (total > bestTotal) {
      bestTotal = total;
      bestIndex = i;
    }
  }
  improvementNotes = evaluation.improvement_notes || '';
  needsRetry = bestTotal < 35;
} else {
  // Evaluation parse failed — use first message, no retry
  bestIndex = 0;
  bestTotal = 0;
  needsRetry = false;
}

const bestMessage = messages[bestIndex] || messages[0];

return [{ json: {
  needsRetry,
  bestMessage,
  bestIndex,
  bestTotal,
  improvementNotes,
  evaluation,
  messages,
  recordId: prev.recordId,
  prospect: prev.prospect
} }];

const data = $('out-select-best').first().json;
const prospect = data.prospect;
const evaluation = data.evaluation;
const messages = data.messages;
const improvementNotes = data.improvementNotes;

// Build critique summary from evaluation
let critiqueSummary = '';
if (evaluation && evaluation.evaluations) {
  critiqueSummary = evaluation.evaluations.map((ev, i) =>
    `Message ${String.fromCharCode(65 + i)} (${ev.angle}): ${ev.total}/50 — ${ev.critique || 'No critique'}`
  ).join('\n');
}

const systemPrompt = `You are Cosmisk's top outreach copywriter. A previous draft scored below 35/50. You must write a significantly better message.

ABSOLUTE BANS — never use these phrases:
- "I hope this email finds you well"
- "I came across your company"
- "I'd love to connect"
- "Let's schedule a quick call"
- "synergy", "game-changer", "best-in-class"

RULES:
1. Open with something SPECIFIC about THEIR business
2. Under 150 words
3. CTA must be a SPECIFIC question
4. Subject line must create curiosity without clickbait`;

const userPrompt = `Your previous 3 attempts all scored below the quality bar. Here's what the evaluator said:

${critiqueSummary}

Improvement direction: ${improvementNotes}

Now write ONE final outreach message that fixes ALL the issues. Combine the best elements from all 3 angles.

Prospect:
- Company: ${prospect.company}
- Contact: ${prospect.contact}
- Platform: ${prospect.platform}
- Profile: ${prospect.profileUrl || 'not provided'}
- Industry: ${prospect.industry || 'unknown'}

Return JSON:
{
  "angle": "refined",
  "subject_line": "...",
  "body": "...",
  "research_note": "..."
}`;

return [{ json: { systemPrompt, userPrompt, recordId: data.recordId, prospect, messages } }];

// Format output from retry path
const geminiResult = $json;
const prev = $('out-build-retry-prompt').first().json;
const prospect = prev.prospect;
const recordId = prev.recordId;

let bestMessage = null;
try {
  const text = (geminiResult.candidates || [])[0]?.content?.parts?.[0]?.text || '';
  let cleaned = text.replace(/^```json\s*/i, '').replace(/^```\s*/m, '').replace(/\s*```\s*$/m, '').trim();
  const jsonMatch = cleaned.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    bestMessage = JSON.parse(jsonMatch[0]);
  }
} catch (e) { /* fallback below */ }

if (!bestMessage || !bestMessage.body) {
  bestMessage = prev.messages[0] || {
    angle: 'fallback',
    subject_line: `Quick question about ${prospect.company || 'your'} ads`,
    body: `Hi ${prospect.contact || 'there'}, most ${prospect.industry || 'D2C'} brands struggle with ad fatigue. We build UGC pipelines that keep fresh creatives flowing. What's your current biggest bottleneck with ad creatives?`,
    research_note: 'Retry parse failed, using best original draft'
  };
}

const research = bestMessage.research_note || '';
const message = bestMessage.body;
const subjectLine = bestMessage.subject_line || '';

// Build follow-up (quick generation)
const followUp = `Hey ${prospect.contact || 'there'}, following up on my note about ${prospect.company ? prospect.company + "'s" : 'your'} ad strategy. Would a 2-min Loom walkthrough of what we'd do differently be helpful? No call needed.`;

const notesUpdate = `\n\n--- AI Research ---\n${research}\n\n--- Draft Message (${prospect.platform}) [Agent: refined after retry] ---\n${message}\n\n--- Follow-up Draft ---\n${followUp}`;

const originalNotes = prospect.notes || `Platform: ${prospect.platform}\nProfile: ${prospect.profileUrl || ''}\nIndustry: ${prospect.industry || ''}`;
const fullNotes = originalNotes + notesUpdate;
const followUpDate = new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

const slackMsg = `:mag: *New Prospect Researched (Agent: Retry Path)*\n\n` +
  `*Company:* ${prospect.company}\n` +
  `*Contact:* ${prospect.contact}\n` +
  `*Platform:* ${prospect.platform}\n` +
  `*Profile:* ${prospect.profileUrl || 'N/A'}\n\n` +
  `*Research:*\n${research}\n\n` +
  `*Draft Message:*\n\`\`\`${message}\`\`\`\n\n` +
  (subjectLine ? `*Subject:* ${subjectLine}\n\n` : '') +
  `*Follow-up Draft:*\n\`\`\`${followUp}\`\`\`\n\n` +
  `_Agent scored all 3 initial drafts below 35/50 and generated a refined version. Copy and send on ${prospect.platform}._`;

return [{ json: { recordId, slackMsg, prospect, patchBody: { fields: { notes: fullNotes, stage: 'contacted', next_follow_up: followUpDate } } } }];

// Format output from no-retry path (best of 3 messages)
const data = $('out-select-best').first().json;
const prospect = data.prospect;
const recordId = data.recordId;
const bestMessage = data.bestMessage;
const bestTotal = data.bestTotal;
const bestIndex = data.bestIndex;

const research = bestMessage.research_note || '';
const message = bestMessage.body;
const subjectLine = bestMessage.subject_line || '';
const angle = bestMessage.angle || 'unknown';

// Build follow-up
const followUp = `Hey ${prospect.contact || 'there'}, following up on my note about ${prospect.company ? prospect.company + "'s" : 'your'} ad strategy. Would a 2-min Loom walkthrough of what we'd do differently be helpful? No call needed.`;

const notesUpdate = `\n\n--- AI Research ---\n${research}\n\n--- Draft Message (${prospect.platform}) [Agent: ${angle}, scored ${bestTotal}/50] ---\n${message}\n\n--- Follow-up Draft ---\n${followUp}`;

const originalNotes = prospect.notes || `Platform: ${prospect.platform}\nProfile: ${prospect.profileUrl || ''}\nIndustry: ${prospect.industry || ''}`;
const fullNotes = originalNotes + notesUpdate;
const followUpDate = new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

const slackMsg = `:mag: *New Prospect Researched (Agent: ${angle} — ${bestTotal}/50)*\n\n` +
  `*Company:* ${prospect.company}\n` +
  `*Contact:* ${prospect.contact}\n` +
  `*Platform:* ${prospect.platform}\n` +
  `*Profile:* ${prospect.profileUrl || 'N/A'}\n\n` +
  `*Research:*\n${research}\n\n` +
  `*Draft Message:*\n\`\`\`${message}\`\`\`\n\n` +
  (subjectLine ? `*Subject:* ${subjectLine}\n\n` : '') +
  `*Follow-up Draft:*\n\`\`\`${followUp}\`\`\`\n\n` +
  `_Agent selected best of 3 drafts (${angle} angle). Copy and send on ${prospect.platform}._`;

return [{ json: { recordId, slackMsg, prospect, patchBody: { fields: { notes: fullNotes, stage: 'contacted', next_follow_up: followUpDate } } } }];

const body = $json.body || $json;
const leadId = body.lead_id || body.record_id || '';
const status = body.status || '';
const notes = body.notes || '';

if (!leadId || !status) {
  return [{ json: { _error: true, message: 'lead_id and status required' } }];
}

const stageMap = {
  'contacted': 'contacted',
  'responded': 'follow_up',
  'interested': 'follow_up',
  'not_interested': 'lost'
};
const stage = stageMap[status] || 'follow_up';

const patchBody = { fields: { stage } };
if (notes) patchBody.fields.notes = notes;
if (status === 'interested') {
  patchBody.fields.next_follow_up = new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString().split('T')[0];
}

return [{ json: { leadId, patchBody, status, _error: false } }];

const response = $json;
const records = response.records || [];

if (records.length === 0) {
  return [{ json: { hasFollowups: false, count: 0, prospects: [] } }];
}

const prospects = records.map(r => ({
  id: r.id,
  company: r.fields.company_name || '',
  contact: r.fields.contact_name || '',
  email: r.fields.email || '',
  channel: r.fields.channel || 'email',
  notes: r.fields.notes || '',
  lastContact: r.fields.next_follow_up || ''
}));

return [{ json: { hasFollowups: true, count: prospects.length, prospects } }];

const data = $json;
const prospects = data.prospects;

const systemPrompt = `You are a sales follow-up assistant for Cosmisk, a UGC agency. Generate personalized follow-up messages for prospects who haven't responded to initial outreach. Messages should be brief, add new value (case study mention, industry insight, or limited offer), and have a clear CTA.`;

let prospectsList = prospects.map((p, i) => 
  `${i + 1}. ${p.company} (${p.contact}) - ${p.channel} - Last contacted: ${p.lastContact}
Previous notes: ${(p.notes || '').substring(0, 200)}`
).join('

');

const userPrompt = `Generate follow-up messages for these ${prospects.length} prospects:

${prospectsList}

For each, provide a JSON array:
[
  { "record_id": "recXXX", "message": "follow-up text", "subject": "email subject or null" }
]

Use the actual record IDs from the prospect data. The record IDs are:
${prospects.map(p => `- ${p.company}: ${p.id}`).join('
')}`;

return [{ json: { systemPrompt, userPrompt, prospects } }];

const geminiResult = $json;
const prospects = $('out-build-followup-prompt').first().json.prospects;

let followups = [];
try {
  const text = geminiResult?.candidates?.[0]?.content?.parts?.[0]?.text || '';
  const jsonMatch = text.match(/\[[\s\S]*\]/);
  if (jsonMatch) {
    followups = JSON.parse(jsonMatch[0]);
  }
} catch (e) {
  followups = prospects.map(p => ({
    record_id: p.id,
    message: `Hi ${p.contact || 'there'}, just following up on my earlier message about how UGC content could help ${p.company || 'your brand'}. We recently helped a brand in your space see 3x better ad performance with authentic creator content. Would love to share the case study - are you free for a quick 10-min call this week?`,
    subject: null
  }));
}

if (followups.length > 0 && !followups[0].record_id && prospects.length === followups.length) {
  followups = followups.map((f, i) => ({ ...f, record_id: prospects[i].id }));
}

let slackMsg = `:repeat: *Daily Outreach Follow-ups (${followups.length} prospects)*\n\n`;
followups.forEach((f, i) => {
  const p = prospects.find(pr => pr.id === f.record_id) || prospects[i] || {};
  slackMsg += `*${i + 1}. ${p.company || 'Unknown'}* (${p.contact || ''}) - ${p.channel || 'email'}\n`;
  if (f.subject) slackMsg += `Subject: ${f.subject}\n`;
  slackMsg += `\`\`\`${f.message}\`\`\`\n\n`;
});
slackMsg += `_Copy and send these follow-ups, then use /mark-outreach to update status._`;

const nextDate = new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
const updates = followups.map(f => ({
  id: f.record_id,
  fields: { next_follow_up: nextDate }
}));

return [{ json: { slackMsg, updates, count: followups.length } }];

// ============================================================
// Prepare batch research prompt for Gemini
// HYPER-PERSONALIZED: uses funding data, ad signals, industry context
// ENHANCED: real portfolio data + same-industry client matching
// ============================================================
const body = $json.body || $json;
const leads = body.leads || [];

if (leads.length === 0) {
  return [{ json: { _skip: true, count: 0, slackMsg: '' } }];
}

// ── Industry → Client Mapping (real Cosmisk/Smashed portfolio) ──
const industryClients = {
  'beauty': ['Suroskie (24 scripts R1)', 'Bare Anatomy', 'Sereko', 'Oziva', 'Sotrue', 'GlowVita', 'Exotic Flora', 'Kyari'],
  'skincare': ['Suroskie (24 scripts R1)', 'Bare Anatomy', 'Sereko', 'Oziva', 'Sotrue', 'GlowVita'],
  'jewelry': ['Elinor', 'Taahira Jewellery', 'Bling Queen', 'Krysstal', 'Helping Hands'],
  'fashion': ['Suroskie', 'MNMLST', 'Bling Queen', 'Elinor'],
  'fintech': ['Wint Wealth (5 rounds, 8 months)', 'Propelld', 'Fixed Income', 'Sahi Trading', 'TFI'],
  'food': ['Cinnamon Kitchen', 'Being Bania', 'Goodbug'],
  'health': ['MenoVeda', 'VARCOLEG CARE', 'Tribal Veda (4 rounds)', 'Goodbug'],
  'wellness': ['MenoVeda', 'VARCOLEG CARE', 'Tribal Veda (4 rounds)', 'Goodbug'],
  'fragrance': ['Ajmal Perfumes (2 rounds)', 'Oudarabia'],
  'perfume': ['Ajmal Perfumes (2 rounds)', 'Oudarabia'],
  'consumer': ['Frido (3 projects)', 'Coolnut', 'Cool Beds', 'FabPad', 'Handme', 'Wheelwash'],
  'automotive': ['Wheelwash'],
  'education': ['Edyoda (6 scripts)'],
  'home': ['Exotic Flora', 'LABHAM HOME', 'Cool Beds'],
  'kids': ['Tribe Kids', 'Brave Paws'],
  'electronics': ['Coolnut', 'Ambrane India', 'Loop Earplugs'],
  'default': ['Mamaearth', 'Ajmal Perfumes', 'Wint Wealth', 'Bare Anatomy']
};

// ── Fuzzy-match lead fields to find same-industry clients ──
function findIndustryClients(lead) {
  const searchText = [
    lead.industry || '',
    lead.signal || '',
    lead.notes || '',
    lead.best_service || '',
    lead.company_name || ''
  ].join(' ').toLowerCase();

  const matched = new Set();
  for (const [key, clients] of Object.entries(industryClients)) {
    if (key === 'default') continue;
    if (searchText.includes(key)) {
      clients.forEach(c => matched.add(c));
    }
  }
  // If no matches, return default marquee names
  if (matched.size === 0) {
    industryClients['default'].forEach(c => matched.add(c));
  }
  return [...matched].slice(0, 6);
}

// ── Build portfolio context per lead ──
function buildPortfolioContext(lead) {
  const sameIndustry = findIndustryClients(lead);
  return `
## PORTFOLIO PROOF POINTS (use these in the message — they are REAL)
- 62 brands served across D2C Beauty, Jewelry, Fintech, Consumer Products, Perfumes, Wellness, Food, Education, Fashion
- 33+ active creators on roster for UGC production
- Standard delivery: 3 hooks per concept, multiple ad variations for A/B testing
- Repeat clients demonstrate trust: Wint Wealth (5 rounds over 8 months), Tribal Veda (4 rounds), Suroskie (24 scripts in Round 1), Ajmal Perfumes (2 rounds), Frido (3 projects)
- Upsell proof: Wint Wealth went from UGC ads to a Rs 4L/month organic content partnership
- Notable names on our roster: Mamaearth, Canva, Ajmal Perfumes, Bare Anatomy, Oziva, Loop Earplugs

## SAME-INDUSTRY EXPERIENCE FOR THIS LEAD
Clients in a similar space: ${sameIndustry.join(', ')}

## OUTREACH RULES (CRITICAL — follow exactly)
1. Reference our work with ${sameIndustry.slice(0, 3).join(', ')} when relevant — use ACTUAL client names from the list above
2. For funded brands: mention we have scaled D2C brands from seed stage (like Basil, GoOAT) to Series A growth (like FableStreet, Rapidbox)
