// Parse Gemini batch research results
// Build: Airtable PATCH body, Slack summary, webhook response
// FIXED: geminiOk detection, removed stage field (causes select error)
// ============================================================
const geminiResult = $json;
const prevData = $('Prep Batch Research').first().json;
const leads = prevData.leads || [];

let results = [];
let geminiOk = false;

try {
  const text = (geminiResult.candidates || [])[0]?.content?.parts?.[0]?.text || '';
  if (!text) throw new Error('No Gemini response');

  // Strip markdown code fences (multiple patterns)
  let cleaned = text
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/m, '')
    .replace(/\s*```\s*$/m, '')
    .trim();

  // Try parsing as array
  const arrMatch = cleaned.match(/\[[\s\S]*\]/);
  if (arrMatch) {
    try {
      results = JSON.parse(arrMatch[0]);
      geminiOk = true;
    } catch (e) {
      // Truncated JSON fallback — extract individual objects
      const objPattern = /\{[^{}]*"company_name"\s*:\s*"[^"]+"[\s\S]*?"platform"\s*:\s*"[^"]+"/g;
      const matches = cleaned.match(objPattern) || [];
      for (const m of matches) {
        try {
          // Close the object
          const fixed = m + (m.endsWith('}') ? '' : '"}');
          results.push(JSON.parse(fixed));
        } catch (e2) { /* skip */ }
      }
      if (results.length > 0) geminiOk = true;
    }
  }

  // If still no results, try parsing as single object with array inside
  if (results.length === 0) {
    try {
      const parsed = JSON.parse(cleaned);
      if (Array.isArray(parsed)) {
        results = parsed;
        geminiOk = true;
      } else if (parsed.results || parsed.prospects) {
        results = parsed.results || parsed.prospects;
        geminiOk = true;
      }
    } catch (e) { /* ignore */ }
  }
} catch (err) {
  // Gemini completely failed
}

// Build Airtable batch PATCH and Slack message
const patchRecords = [];
const slackLines = [`:mag: *Outreach — ${leads.length} Prospects Researched & Messages Drafted*\n`];
const followUpDate = new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

for (const lead of leads) {
  // Match by company name (case-insensitive, trimmed)
  const leadName = (lead.company_name || '').toLowerCase().trim();
  const match = results.find(r =>
    (r.company_name || '').toLowerCase().trim() === leadName
  );

  let research = '';
  let message = '';
  let followUp = '';
  let platform = lead.suggested_platform || 'email';
  let subjectLine = '';
  let hooks = [];
  let wasPersonalized = false;

  if (match) {
    research = Array.isArray(match.research) ? match.research.join('\n') : (match.research || '');
    message = match.message || '';
    followUp = match.follow_up || '';
    platform = match.platform || platform;
    subjectLine = match.subject_line || '';
    hooks = match.personalization_hooks || [];
    wasPersonalized = true;
  }

  // Only use fallback if Gemini completely failed
  if (!message) {
    const hook = lead.pitch_hook || '';
    message = hook || `Hi, I noticed ${lead.company_name} is growing fast. We specialize in UGC ads that help consumer brands scale their paid media. Would you be open to a free creative audit?`;
    followUp = `Following up — we just published a case study on how UGC reduced CPA by 40% for a brand in your space. Happy to share if helpful.`;
    research = 'Gemini did not return a result for this company';
  }

  // Build enriched notes (append to existing)
  const notesAppend = `\n\n--- AI Research (${geminiOk ? 'Gemini' : 'fallback'}) ---\n${research}\n\n--- Draft Outreach (${platform}) ---\n${subjectLine ? 'Subject: ' + subjectLine + '\n' : ''}${message}\n\n--- Follow-up Draft ---\n${followUp}${hooks.length ? '\n\nPersonalization hooks: ' + hooks.join(', ') : ''}`;
  const fullNotes = (lead.notes || '') + notesAppend;

  // DO NOT set stage — stage changes when outreach is actually sent
  patchRecords.push({
    id: lead.record_id,
    fields: {
      notes: fullNotes,
      next_follow_up: followUpDate
    }
  });

  const personalBadge = wasPersonalized ? ':sparkles:' : ':warning:';
  slackLines.push(
    `${personalBadge} *${lead.company_name}*` +
    (lead.industry ? ` (${lead.industry})` : '') +
    `\n  Platform: ${platform}` +
    (subjectLine ? ` | Subject: _${subjectLine}_` : '') +
    `\n  Message: "${message.substring(0, 150)}..."` +
    (hooks.length ? `\n  :dart: Hooks: ${hooks.join(', ')}` : '') +
    `\n  Follow-up: ${followUpDate}\n`
  );
}

slackLines.push(geminiOk
  ? `\n:white_check_mark: _${results.length} prospects researched via Gemini. Messages in Airtable notes — review, customize, and send._`
  : `\n:warning: _Gemini failed — fallback messages used. Review and heavily customize before sending._`
);

return [{ json: {
  patchBody: JSON.stringify({ records: patchRecords }),
  slackMsg: slackLines.join('\n'),
  count: patchRecords.length,
  geminiOk,
  enriched: true
} }];

