// ── Fuzzy-match lead fields to find same-industry clients ──
function findIndustryClients(lead) {
  const searchText = [
    lead.industry || '',
    lead.signal || '',
    lead.notes || '',
    lead.best_service || '',
    lead.company_name || ''
  ].join(' ').toLowerCase();

  const matched = new Set();
  for (const [key, clients] of Object.entries(industryClients)) {
    if (key === 'default') continue;
    if (searchText.includes(key)) {
      clients.forEach(c => matched.add(c));
    }
  }
  // If no matches, return default marquee names
  if (matched.size === 0) {
    industryClients['default'].forEach(c => matched.add(c));
  }
  return [...matched].slice(0, 6);
}

